<?php
declare(strict_types=1);require dirname(__DIR__).'/config/bootstrap.php';$user=require_role('admin');$users=db()->query('SELECT id,username,email,full_name,role,approval_status,is_active,created_at FROM users ORDER BY created_at DESC')->fetchAll();$pageTitle='Persetujuan & Manajemen Akun';require ROOT_PATH.'/includes/header.php';?>
<div class="page-head"><div><p class="eyebrow">Keamanan Akses</p><h1 class="page-title">Persetujuan & Manajemen Akun</h1><p class="page-description">Buat akun internal, setujui Guru, ubah role dan password, serta hapus akun dengan aman.</p></div><button class="btn btn-primary" data-modal-open="create-account">+ Buat Akun</button></div><section class="card"><div class="filter-row"><input class="input" data-search-table="#users-table" placeholder="Cari nama, username, email, atau role..."><span class="badge badge-blue"><?= count($users) ?> Pengguna</span></div><div class="table-wrap"><table class="table" id="users-table"><thead><tr><th>Nama</th><th>Username/Email</th><th>Role</th><th>Persetujuan</th><th>Status</th><th>Aksi</th></tr></thead><tbody><?php foreach($users as $account):?><tr><td class="name"><?= e($account['full_name']) ?></td><td><?= e($account['username']) ?><br><small class="muted"><?= e($account['email']?:'Email opsional') ?></small></td><td><span class="badge badge-blue"><?= e(str_replace('_',' ',$account['role'])) ?></span></td><td><span class="badge <?= $account['approval_status']==='approved'?'badge-green':($account['approval_status']==='pending'?'badge-yellow':'badge-red') ?>"><?= e($account['approval_status']) ?></span></td><td><span class="badge <?= $account['is_active']?'badge-green':'badge-gray' ?>"><?= $account['is_active']?'Aktif':'Nonaktif' ?></span></td><td><details><summary class="btn btn-soft btn-sm">Kelola</summary><div class="grid" style="min-width:280px;padding:12px 0"><form action="<?= url('api/users/index.php') ?>" method="post" data-ajax class="actions"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= e($account['id']) ?>"><?php if($account['approval_status']==='pending'):?><button class="btn btn-primary btn-sm" name="action" value="approve">Setujui</button><button class="btn btn-danger btn-sm" name="action" value="reject">Tolak</button><?php endif;?><input type="hidden" name="active" value="<?= $account['is_active']?'0':'1' ?>"><button class="btn btn-warning btn-sm" name="action" value="toggle_active"><?= $account['is_active']?'Nonaktifkan':'Aktifkan' ?></button></form><form action="<?= url('api/users/index.php') ?>" method="post" data-ajax class="actions"><?= csrf_field() ?><input type="hidden" name="action" value="change_role"><input type="hidden" name="user_id" value="<?= e($account['id']) ?>"><select class="select" name="role"><?php foreach(['admin','guru','orang_tua'] as $role):?><option value="<?= $role ?>" <?= $account['role']===$role?'selected':'' ?>><?= e(str_replace('_',' ',$role)) ?></option><?php endforeach;?></select><button class="btn btn-blue btn-sm">Ubah Role</button></form><form action="<?= url('api/users/index.php') ?>" method="post" data-ajax class="grid"><?= csrf_field() ?><input type="hidden" name="action" value="change_password"><input type="hidden" name="user_id" value="<?= e($account['id']) ?>"><input class="input" type="password" name="password" minlength="8" placeholder="Password baru" required><input class="input" type="password" name="password_confirmation" minlength="8" placeholder="Konfirmasi password" required><button class="btn btn-soft btn-sm">Ubah Password</button></form><?php if($account['id']!==$user['id']):?><form action="<?= url('api/users/index.php') ?>" method="post" data-ajax><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="user_id" value="<?= e($account['id']) ?>"><button class="btn btn-danger btn-sm" data-confirm="Hapus akun beserta data profil terkait?">Hapus Akun</button></form><?php endif;?></div></details></td></tr><?php endforeach;?></tbody></table></div></section>
<div class="modal" id="create-account"><div class="modal-card"><div class="modal-head"><div><p class="eyebrow">Akun Internal</p><h2>Buat Akun Baru</h2></div><button class="modal-close" data-modal-close>×</button></div><form action="<?= url('api/users/index.php') ?>" method="post" data-ajax class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="create"><div class="field full"><label>Nama Lengkap</label><input class="input" name="full_name" required></div><div class="field"><label>Username</label><input class="input" name="username" pattern="[A-Za-z0-9._-]{3,80}" required></div><div class="field"><label>Email (opsional)</label><input class="input" type="email" name="email"></div><div class="field"><label>Role</label><select class="select" name="role"><option value="guru">Guru</option><option value="orang_tua">Orang Tua</option><option value="admin">Admin</option></select></div><div></div><div class="field"><label>Password</label><input class="input" type="password" name="password" minlength="8" required></div><div class="field"><label>Konfirmasi Password</label><input class="input" type="password" name="password_confirmation" minlength="8" required></div><button class="btn btn-primary field full">Buat Akun Tanpa Verifikasi Email</button></form></div></div><?php require ROOT_PATH.'/includes/footer.php';?>

